import type { FoundationIR } from '@expo-foundation/core';
import { defaultDependencyManager } from '../dependency-manager/index.js';

export interface GeneratedConfigFile {
  path: string;
  content: string;
  ownership: 'generated' | 'user-protected';
}

const GENERATED_HEADER = `/**
 * @generated by @expo-foundation/expo-generator
 * DO NOT EDIT MANUALLY — deterministic output from Canonical FoundationIR.
 */`;

export function generateProjectConfigFiles(ir: FoundationIR): GeneratedConfigFile[] {
  const deps = defaultDependencyManager.resolveForIR(ir);
  const scheme = ir.navigation?.linking.scheme ?? 'expofoundation';
  const hosts = ir.navigation?.linking.hosts ?? ['example.com'];
  const plugins: string[] = [];

  if (ir.navigation) {
    plugins.push('expo-router');
  }
  if (ir.auth && ir.auth.enabled) {
    plugins.push('expo-secure-store');
    if (ir.auth.authMethods.apple || ir.auth.primaryProvider.type === 'apple') {
      plugins.push('expo-apple-authentication');
    }
  }

  const appJson = {
    expo: {
      name: ir.projectMetadata.projectId,
      slug: ir.projectMetadata.projectId,
      version: '1.0.0',
      sdkVersion: deps.sdkVersion,
      scheme,
      platforms: ['ios', 'android'],
      ios: {
        supportsTablet: true,
        bundleIdentifier: `com.expofoundation.${ir.projectMetadata.projectId.replace(/[^a-zA-Z0-9]/g, '')}`,
        associatedDomains: ir.navigation?.linking.universalLinks
          ? hosts.map((h) => `applinks:${h}`)
          : [],
      },
      android: {
        package: `com.expofoundation.${ir.projectMetadata.projectId.replace(/[^a-zA-Z0-9]/g, '')}`,
        intentFilters: ir.navigation?.linking.androidAppLinks
          ? hosts.map((host) => ({
              action: 'VIEW',
              autoVerify: true,
              data: [{ scheme: 'https', host, pathPrefix: '/' }],
              category: ['BROWSABLE', 'DEFAULT'],
            }))
          : [],
      },
      plugins,
      experiments: {
        typedRoutes: true,
      },
    },
  };

  const packageJson = {
    name: ir.projectMetadata.projectId,
    version: '1.0.0',
    private: true,
    main: ir.navigation ? 'expo-router/entry' : 'src/foundation/auth/AuthController.ts',
    scripts: {
      start: 'expo start',
      ios: 'expo run:ios',
      android: 'expo run:android',
      typecheck: 'tsc --noEmit',
      test: 'jest',
    },
    dependencies: deps.dependencies,
    devDependencies: deps.devDependencies,
  };

  const tsconfigJson = {
    extends: 'expo/tsconfig.base',
    compilerOptions: {
      strict: true,
      baseUrl: '.',
      paths: {
        '@/*': ['./src/*'],
      },
    },
    include: ['**/*.ts', '**/*.tsx'],
  };

  const allScreenRefs = new Set<string>();
  if (ir.auth) {
    for (const ref of Object.values(ir.auth.screenRefs)) {
      allScreenRefs.add(ref);
    }
  }
  if (ir.navigation) {
    for (const ref of ir.navigation.screenRefs) {
      allScreenRefs.add(ref);
    }
  }
  const sortedScreenRefs = Array.from(allScreenRefs).sort();

  const screenUnionType =
    sortedScreenRefs.length > 0
      ? sortedScreenRefs.map((s) => `'${s}'`).join(' | ')
      : 'string';

  return [
    {
      path: 'app.json',
      ownership: 'generated',
      content: `${JSON.stringify(appJson, null, 2)}\n`,
    },
    {
      path: 'package.json',
      ownership: 'generated',
      content: `${JSON.stringify(packageJson, null, 2)}\n`,
    },
    {
      path: 'tsconfig.json',
      ownership: 'generated',
      content: `${JSON.stringify(tsconfigJson, null, 2)}\n`,
    },
    {
      path: 'src/types/foundation.generated.ts',
      ownership: 'generated',
      content: `${GENERATED_HEADER}

export type RegisteredScreenId = ${screenUnionType};

export interface ScreenMetadata {
  id: RegisteredScreenId;
  title?: string;
  required?: boolean;
}

export interface ScreenRegistryContract {
  has(screenId: string): boolean;
  resolve(screenId: string): ((props: any) => any) | undefined;
  getMetadata(screenId: string): ScreenMetadata | undefined;
}
`,
    },
    {
      path: 'src/screens/registry.ts',
      ownership: 'user-protected',
      content: `/**
 * User-Owned Screen Registry
 *
 * Register your externally developed screen components or Screen Builder outputs here.
 * This file is protected across incremental regenerations and will never be overwritten.
 */
import type { RegisteredScreenId, ScreenMetadata, ScreenRegistryContract } from '../types/foundation.generated';

class ApplicationScreenRegistry implements ScreenRegistryContract {
  private readonly screens = new Map<string, (props: any) => any>();
  private readonly metadata = new Map<string, ScreenMetadata>();

  register(
    screenId: RegisteredScreenId,
    component: (props: any) => any,
    meta?: Omit<ScreenMetadata, 'id'>
  ): void {
    this.screens.set(screenId, component);
    this.metadata.set(screenId, { id: screenId, ...meta });
  }

  has(screenId: string): boolean {
    return this.screens.has(screenId);
  }

  resolve(screenId: string): ((props: any) => any) | undefined {
    return this.screens.get(screenId);
  }

  getMetadata(screenId: string): ScreenMetadata | undefined {
    return this.metadata.get(screenId);
  }
}

export const screenRegistry = new ApplicationScreenRegistry();

// Required screen IDs referenced by Auth & Navigation configuration:
${sortedScreenRefs.map((ref) => `// - "${ref}"`).join('\n')}
`,
    },
  ];
}
